s=s.replace("setTimeout(refresh,1400);setInterval", "const offersAuthView=document.getElementById('appView');if(offersAuthView)new MutationObserver(()=>{if(!offersAuthView.classList.contains('hidden'))refresh()}).observe(offersAuthView,{attributes:true,attributeFilter:['class']});const offersRoleBadge=document.getElementById('roleBadge');let offersLastRole=role();if(offersRoleBadge)new MutationObserver(()=>{const next=role();if(next!==offersLastRole){offersLastRole=next;refresh()}}).observe(offersRoleBadge,{childList:true,characterData:true,subtree:true});setTimeout(refresh,1400);setInterval");
