if(s.includes('dextersPointsLiveScript')){console.log('points live already present');process.exit(0)}
const addon=String.raw`<style id="dextersPointsLiveStyle">
#workRewards .dx-points-summary{margin-top:11px;padding-top:10px;border-top:1px solid #ffffff20}.dx-points-top{display:flex;align-items:flex-end;justify-content:space-between;gap:8px}.dx-points-num{font-size:24px;font-weight:950}.dx-points-value{font-size:11px;color:var(--yellow);font-weight:900}.dx-free-box{margin-top:8px;padding:9px;border-radius:12px;background:var(--navy2)}.dx-kicker{font-size:9px;color:var(--muted);font-weight:900;text-transform:uppercase;letter-spacing:.45px}.dx-free-name{font-size:12px;font-weight:900;margin-top:3px;line-height:1.3}.dx-cat{display:inline-block;margin-top:6px;padding:4px 7px;border-radius:999px;background:var(--yellow);color:#111;font-size:9px;font-weight:950;text-transform:uppercase;letter-spacing:.3px}.dx-points-card{margin-top:14px}.dx-points-balance{font-size:36px;font-weight:950}.dx-points-note{margin-top:10px;padding:11px 12px;border-radius:13px;background:var(--navy2);color:var(--muted);font-size:12px;line-height:1.5}.dx-reward-row{padding:11px 0;border-top:1px solid #ffffff18}.dx-reward-row:first-child{border-top:0}.dx-reward-head{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}.dx-free-pill{display:inline-block;padding:4px 7px;border-radius:999px;background:var(--yellow);color:#111;font-size:9px;font-weight:950;white-space:nowrap}.dx-next-progress{height:7px;background:var(--navy2);border-radius:999px;overflow:hidden;margin-top:8px}.dx-next-progress>span{display:block;height:100%;background:var(--yellow)}#dxStaffPointsCard .dx-staff-customer{margin:10px 0;padding:11px;border-radius:13px;background:var(--navy2)}#dxStaffPointsCard .dx-staff-grid{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px;align-items:end}#dxStaffPointsCard .dx-staff-grid .btn{width:auto}.dx-points-status{font-size:12px;margin-top:9px}.dx-points-ok{color:#9ff3c5}.dx-points-err{color:#ffc1cb}
</style><script id="dextersPointsLiveScript">(function(){
'use strict';
var U='https://bpnkouymdvcogeaqjmxl.supabase.co',K='sb_publishable_v6rJbF4IfGZTKtbuQtmsmQ_lS3sXWFa',fixture=document.documentElement.dataset.layoutFixture==='true';
var $=function(id){return document.getElementById(id)};
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function token(){try{var j=JSON.parse(localStorage.getItem('sb-bpnkouymdvcogeaqjmxl-auth-token')||'null');return j&&((j.currentSession&&j.currentSession.access_token)||(j.session&&j.session.access_token)||j.access_token)||''}catch(e){return''}}
async function api(body){var t=token();if(!t)throw new Error('Sign in to view points.');var r=await fetch(U+'/functions/v1/loyalty-points-api',{method:'POST',headers:{apikey:K,Authorization:'Bearer '+t,'Content-Type':'application/json'},body:JSON.stringify(body)});var d=await r.json();if(!r.ok)throw new Error(d.error||'Points unavailable');return d}
var sample={points:650,value_gbp:'6.50',rewards:[{name:'Can of Juice',category:'Drinks',points_required:135},{name:'Chicken Mayo Melt',category:"Dexter’s Street Subs",points_required:650},{name:'Pepperoni & Cheese Street Sub',category:"Dexter’s Street Subs",points_required:650}],next_reward:{name:'Southern Fried Chicken Street Sub',category:"Dexter’s Street Subs",points_required:700}};
function summaryHtml(d){var best=(d.rewards||[]).slice().sort(function(a,b){return b.points_required-a.points_required})[0];return '<div class="dx-points-summary"><div class="dx-points-top"><div><div class="dx-points-num">'+esc(d.points||0)+'</div><div class="wd">points</div></div><div class="dx-points-value">£'+esc(d.value_gbp||'0.00')+'</div></div>'+(best?'<div class="dx-free-box"><div class="dx-kicker">Free now</div><div class="dx-free-name">'+esc(best.name)+'</div><div class="dx-cat">'+esc(best.category)+'</div></div>':'<div class="dx-free-box"><div class="dx-kicker">Free now</div><div class="dx-free-name">Keep collecting</div></div>')+'</div>'}
function rewardsHtml(d){var rows=(d.rewards||[]).slice().sort(function(a,b){return b.points_required-a.points_required}).map(function(x){return '<div class="dx-reward-row"><div class="dx-reward-head"><div><strong>'+esc(x.name)+'</strong><div class="dx-cat">'+esc(x.category)+'</div><div class="tiny muted" style="margin-top:5px">'+esc(x.points_required)+' points</div></div><span class="dx-free-pill">FREE NOW</span></div></div>'}).join('');var n=d.next_reward;var pct=n?Math.min(100,Math.round((Number(d.points||0)/Number(n.points_required||1))*100)):100;return '<h2>⭐ Dexter’s Points</h2><div class="dx-points-balance">'+esc(d.points||0)+'</div><div class="muted">points · worth £'+esc(d.value_gbp||'0.00')+'</div><div class="dx-points-note"><b style="color:var(--white)">1 point for every full £1 spent.</b> Pence do not round up. Collection orders placed in the Dexter’s app are added automatically only when the order is marked <b style="color:var(--white)">Collected</b>. For other purchases, staff scan your existing Dexter’s QR and enter the final order value.<br><br><b style="color:var(--white)">1 point = £0.01 reward value.</b></div><h3 style="margin-top:18px">What you can get free</h3>'+(rows||'<p class="muted">No full menu item unlocked yet.</p>')+(n?'<h3 style="margin-top:18px">Next free item</h3><strong>'+esc(n.name)+'</strong><div class="dx-cat">'+esc(n.category)+'</div><div class="tiny muted" style="margin-top:6px">'+Math.max(0,Number(n.points_required)-Number(d.points||0))+' points to go</div><div class="dx-next-progress"><span style="width:'+pct+'%"></span></div>':'')}
function ensureUi(){var wr=$('workRewards');if(wr&&!$('dxHomePoints')){var box=document.createElement('div');box.id='dxHomePoints';wr.appendChild(box)}var qr=$('qrPage');if(qr&&!$('dxRewardsPointsCard')){var c=document.createElement('div');c.className='card dx-points-card';c.id='dxRewardsPointsCard';var first=qr.querySelector('.card');if(first&&first.nextSibling)qr.insertBefore(c,first.nextSibling);else qr.appendChild(c)}var staff=$('staffPage'),base=$('staffLoyaltyCard');if(staff&&base&&!$('dxStaffPointsCard')){var c2=document.createElement('div');c2.className='card';c2.id='dxStaffPointsCard';c2.innerHTML='<h2>⭐ Customer Points</h2><p class="muted">Use the customer’s existing Dexter’s QR scanner above. Once the 6-digit loyalty code is filled in, check their points, enter the final order value, then confirm.</p><button id="dxPointsLookup" class="btn secondary" type="button">Use scanned customer</button><div id="dxStaffCustomer" class="dx-staff-customer hidden"></div><label>Final order value</label><div class="dx-staff-grid"><input id="dxOrderValue" class="input" type="number" min="1" step="0.01" placeholder="e.g. 12.80"><button id="dxAddPoints" class="btn primary" type="button" disabled>Add points</button></div><div id="dxPointsCalc" class="tiny muted">1 point for every full £1 spent.</div><div id="dxPointsStatus" class="dx-points-status"></div>';base.after(c2);wireStaff()}}
var currentCustomer=null;
function wireStaff(){var lookup=$('dxPointsLookup'),add=$('dxAddPoints'),amt=$('dxOrderValue'),code=$('staffCode');if(!lookup||lookup.dataset.wired)return;lookup.dataset.wired='1';lookup.onclick=lookupCustomer;if(code)code.addEventListener('input',function(){if(String(code.value||'').replace(/\D/g,'').length===6)setTimeout(lookupCustomer,150)});amt.addEventListener('input',function(){var v=Math.max(0,Number(amt.value||0)),p=Math.floor(v);$('dxPointsCalc').textContent='£'+v.toFixed(2)+' = '+p+' point'+(p===1?'':'s');add.disabled=!currentCustomer||p<1});add.onclick=addPoints}
async function lookupCustomer(){var code=$('staffCode');var val=String(code&&code.value||'').replace(/\D/g,'').slice(0,6),status=$('dxPointsStatus');if(val.length!==6){status.textContent='Scan the customer QR or enter the 6-digit code above.';status.className='dx-points-status dx-points-err';return}try{var d=fixture?{customer:{id:'fixture-customer',full_name:'Layout sample',loyalty_code:val,points:650}}:await api({action:'lookup',loyalty_code:val});currentCustomer=d.customer;var box=$('dxStaffCustomer');box.classList.remove('hidden');box.innerHTML='<strong>'+esc(currentCustomer.full_name)+'</strong><div class="tiny muted">Code '+esc(currentCustomer.loyalty_code)+' · '+esc(currentCustomer.points)+' points</div>';$('dxAddPoints').disabled=Math.floor(Number($('dxOrderValue').value||0))<1;status.textContent='Customer ready.';status.className='dx-points-status dx-points-ok'}catch(e){currentCustomer=null;$('dxAddPoints').disabled=true;status.textContent=e.message;status.className='dx-points-status dx-points-err'}}
