async function refresh(){ensureUi();var home=$('dxHomePoints'),card=$('dxRewardsPointsCard');if(!home&&!card)return;try{var d=fixture?sample:await api({action:'me'});if(home)home.innerHTML=summaryHtml(d);if(card)card.innerHTML=rewardsHtml(d)}catch(e){if(home)home.innerHTML='<div class="dx-points-summary"><div class="wd">Points will appear after sign in.</div></div>';if(card)card.innerHTML='<h2>⭐ Dexter’s Points</h2><p class="muted">'+esc(e.message)+'</p>'}}
function start(){ensureUi();refresh();setTimeout(ensureUi,500);setTimeout(refresh,900);new MutationObserver(function(){ensureUi()}).observe(document.body,{childList:true,subtree:true});document.addEventListener('visibilitychange',function(){if(!document.hidden)refresh()});setInterval(function(){if(!document.hidden)refresh()},20000)}
